if($user && password_verify($password,$user['password_hash'])){session_regenerate_id(true);unset($_SESSION['admin_id'], $_SESSION['admin_name']);$_SESSION['tourist_id']=(int)$user['tourist_id'];$_SESSION['tourist_name']=trim($user['first_name'].' '.$user['last_name']);header('Location: dashboard.php');exit;}
$a=$pdo->prepare("SELECT * FROM administrators WHERE email=?");$a->execute([$email]);$admin=$a->fetch();
if($admin && password_verify($password,$admin['password_hash'])){session_regenerate_id(true);unset($_SESSION['tourist_id'], $_SESSION['tourist_name']);$_SESSION['admin_id']=(int)$admin['admin_id'];$_SESSION['admin_name']=$admin['name'];header('Location: admin/index.php');exit;}
$error='Email or password is incorrect.';}
require 'includes/header.php';?>
